"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[27657],{73925:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"TrainFuelGuiController","desc":"Drives the authored `TrainFuelGui` HUD without issuing any network packets.\\nOn every `RenderStepped` frame it asks `TrainStateCache` for the extrapolated\\nfuel level and eases the displayed level toward it with frame-rate-independent\\nexponential smoothing, so refuel jumps animate smoothly.\\n\\nThe bar is 10 equal cells (same build as `HealthStaminaGui`); cell i shows\\n`clamp(pct * 10 - (i - 1), 0, 1)` as the X scale of its `Fill`.\\n\\n```\\nMainContainer (UICorner, UIStroke, UIScale)\\n\u251c\u2500\u2500 DecoLayer { Rail, Dot1, Dot2, Dot3, Tail, Tick }\\n\u2514\u2500\u2500 Content (UIPadding, UIListLayout horizontal)\\n    \u251c\u2500\u2500 Tag { Icon, Label }\\n    \u251c\u2500\u2500 Well (UIStroke) \u2192 Cells \u2192 Cell1..10 { Fill { Shade } }\\n    \u2514\u2500\u2500 Value\\n```\\n\\nStates: running (mint fill), braked (amber fill), coast (Emergency\\nGenerator: orange well stroke + deco, \\"COAST 12s\\"), stalled (well stroke +\\ndeco pulse red/rust, \\"STALLED\\") and waiting (no snapshot yet: muted, \\"\u2014\\").\\nCoast and stall both happen at 0 fuel, so the well stroke carries them.\\n\\nThis controller holds no fallback snapshot. It previously seeded one from\\n`TrainConfig` plus `workspace:GetServerTimeNow()` read at module load \u2014\\nbefore the client\'s clock estimate had converged \u2014 which extrapolated to a\\nclamped 0% and disagreed with the diegetic monitor. While the server has not\\nyet sent a snapshot the HUD shows a placeholder instead of a guess.","realm":["Client"],"source":{"line":35,"path":"src/StarterPlayer/StarterPlayerScripts/TrainFuelGuiController.client.luau"}}')}}]);